import{_ as l,a0 as n,w as a,s as p,ao as m,I as i,x as t,a1 as s,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"如何設置 Linux 上 SSH 登錄的 Email 提醒 | LCTT x X-CMD","titleTemplate":false,"description":"如何設置 Linux 上 SSH 登錄的 Email 提醒 | LCTT (201504) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何設置 Linux 上 SSH 登錄的 Email 提醒 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何設置 Linux 上 SSH 登錄的 Email 提醒 | LCTT (201504) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201504/20150310 How To Get Email Alerts for SSH Login on Linux Server","title":"如何設置 Linux 上 SSH 登錄的 Email 提醒","tag":"201504","desc":""},"relativePath":"201504/20150310 How To Get Email Alerts for SSH Login on Linux Server.md","filePath":"[post].md"}'),u={name:"201504/20150310 How To Get Email Alerts for SSH Login on Linux Server.md"};function f(c,o,d,S,h,w){const e=n("Link");return a(),p("div",null,[o[13]||(o[13]=m('<h1 id="如何設置-linux-上-ssh-登錄的-email-提醒" tabindex="-1">如何設置 Linux 上 SSH 登錄的 Email 提醒 <a class="header-anchor" href="#如何設置-linux-上-ssh-登錄的-email-提醒" aria-label="Permalink to “如何設置 Linux 上 SSH 登錄的 Email 提醒”">​</a></h1><p><img src="http://www.ehowstuff.com/wp-content/uploads/2015/03/fail2ban-security.jpg" alt=""></p><p>虛擬私有服務器 （VPS）上啓用 SSH 服務使得該服務器暴露到互聯網中，為黑客攻擊提供了機會，尤其是當 VPS 還允許root 直接訪問時。VPS 應該為每次 SSH 登錄成功嘗試配置一個自動的 email 警告。 VPS 服務器的所有者會得到各種 SSH 服務器訪問日誌的通知，例如登錄者、登錄時間以及來源 IP 地址等信息。這是一個對於服務器擁有者來説，保護服務器避免未知登錄嘗試的重要安全關注點。這是因為如果黑客使用暴力破解方式通過 SSH 來登錄到你的 VPS 的話，後果很嚴重。在本文中，我會解釋如何在 CentOS 6、 CentOS 7、 RHEL 6 和 RHEL 7上為所有的 SSH 用户登錄設置一個 email 警告。</p><ol><li><p>使用root用户登錄到你的服務器；</p></li><li><p>在全局源定義處配置警告（/etc/bashrc），這樣就會對 root 用户以及普通用户都生效：</p><pre><code> [root@vps ~]# vi /etc/bashrc\n</code></pre><p>將下面的內容加入到上述文件的尾部。</p><pre><code> echo &#39;ALERT - Root Shell Access (vps.ehowstuff.com) on:&#39; `date` `who` | mail -s &quot;Alert: Root Access from `who | cut -d&#39;(&#39; -f2 | cut -d&#39;)&#39; -f1`&quot; recipient@gmail.com\n</code></pre></li><li><p>你也可以選擇性地讓警告只對 root 用户生效：</p><pre><code> [root@vps ~]# vi .bashrc\n</code></pre><p>將下面的內容添加到/root/.bashrc的尾部：</p><pre><code> echo &#39;ALERT - Root Shell Access (vps.ehowstuff.com) on:&#39; `date` `who` | mail -s &quot;Alert: Root Access from `who | cut -d&#39;(&#39; -f2 | cut -d&#39;)&#39; -f1`&quot; recipient@gmail.com\n</code></pre><p>整個配置文件樣例：</p><pre><code> # .bashrc\n\n # User specific aliases and functions\n\n alias rm=&#39;rm -i&#39;\n alias cp=&#39;cp -i&#39;\n alias mv=&#39;mv -i&#39;\n\n # Source global definitions\n if [ -f /etc/bashrc ]; then\n     	. /etc/bashrc\n fi\n echo &#39;ALERT - Root Shell Access (vps.ehowstuff.com) on:&#39; `date` `who` | mail -s &quot;Alert: Root Access from `who | cut -d&#39;(&#39; -f2 | cut -d&#39;)&#39; -f1`&quot; recipient@gmail.com\n</code></pre></li><li><p>你也可以選擇性地讓警告只對特定的普通用户生效（例如 skytech）：</p><pre><code> [root@vps ~]# vi /home/skytech/.bashrc\n</code></pre><p>將下面的內容加入到/home/skytech/.bashrc文件尾部：</p><pre><code> echo &#39;ALERT - Root Shell Access (vps.ehowstuff.com) on:&#39; `date` `who` | mail -s &quot;Alert: Root Access from `who | cut -d&#39;(&#39; -f2 | cut -d&#39;)&#39; -f1`&quot; recipient@gmail.com\n</code></pre></li></ol><hr>',5)),i("p",null,[o[1]||(o[1]=t("via: ",-1)),s(e,{href:"http://www.ehowstuff.com/how-to-get-email-alerts-for-ssh-login-on-linux-server/"},{default:r(()=>[...o[0]||(o[0]=[t("http://www.ehowstuff.com/how-to-get-email-alerts-for-ssh-login-on-linux-server/",-1)])]),_:1})]),i("p",null,[o[5]||(o[5]=t("作者：",-1)),s(e,{href:"http://www.ehowstuff.com/author/mhstar/"},{default:r(()=>[...o[2]||(o[2]=[t("skytech",-1)])]),_:1}),o[6]||(o[6]=t(" 譯者：",-1)),s(e,{href:"https://github.com/theo-l"},{default:r(()=>[...o[3]||(o[3]=[t("theo-l",-1)])]),_:1}),o[7]||(o[7]=t(" 校對：",-1)),s(e,{href:"https://github.com/wxy"},{default:r(()=>[...o[4]||(o[4]=[t("wxy",-1)])]),_:1})]),i("p",null,[o[10]||(o[10]=t("本文由 ",-1)),s(e,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...o[8]||(o[8]=[t("LCTT",-1)])]),_:1}),o[11]||(o[11]=t(" 原創翻譯，",-1)),s(e,{href:"http://linux.cn/"},{default:r(()=>[...o[9]||(o[9]=[t("Linux中國",-1)])]),_:1}),o[12]||(o[12]=t(" 榮譽推出",-1))])])}const A=l(u,[["render",f]]);export{x as __pageData,A as default};
